      <h1 class="almanac-title almanac-title-sm">${E()?'\u5408\u4E0A\u7B14\u8BB0\u672C\u7684\u90A3\u4E00\u79D2<br/>\u7AD9\u5728\u95E8\u5916\u65F6\u2014\u2014<br/><span class="almanac-title-accent">\u7089\u706B\u4E00\u76F4\u6CA1\u706D\u3002</span>':'Close the laptop \u2014<br/>step out the door \u2014<br/><span class="almanac-title-accent">the hearth never cooled.</span>'}</h1>
